function updateProductCount(products) {
    const productCount = document.getElementById('product-count');
    productCount.textContent = products.length;
}

function sortProducts(products, sortBy) {
    switch (sortBy) {
        case 'alphabetical':
            return products.sort((a, b) => a.name.localeCompare(b.name));
        case 'price-asc':
            return products.sort((a, b) => parseFloat(a.price) - parseFloat(b.price));
        case 'price-desc':
            return products.sort((a, b) => parseFloat(b.price) - parseFloat(a.price));
        case 'availability':
            return products.sort((a, b) => a.availability.localeCompare(b.availability));
        default:
            return products;
    }
}

function filterProductsByKeyword(products, query) {
    const keywords = query.toLowerCase().split(' '); 

    return products.filter(product => {
        const productName = product.name.toLowerCase();
        const productDescription = product.description.toLowerCase();
        const productCategory = product.category.toLowerCase();

        return keywords.some(keyword => 
            productName.includes(keyword) || 
            productDescription.includes(keyword) ||
            productCategory.includes(keyword)
        );
    });
}

function filterProductsByCategory(products, category) {
    return category ? products.filter(product => product.category === category) : products;
}

function filterProductsByBrand(products, brand) {
    return brand ? products.filter(product => product.brand === brand) : products;
}

function filterProductsByPrice(products, maxPrice) {
    return products.filter(product => parseFloat(product.price.replace('€', '').trim()) <= maxPrice);
}

function filterProductsByStock(products, inStockOnly) {
    return inStockOnly ? products.filter(product => product.availability === "En stock") : products;
}

function applyAllFilters() {
    const category = document.getElementById('category-select').value;
    const brand = document.getElementById('brand-select').value;
    const maxPrice = parseFloat(document.getElementById('price-range').value);
    const inStockOnly = document.getElementById('in-stock-only').checked;

    let filteredProducts = productData;

    if (searchQuery) {
        filteredProducts = filterProductsByKeyword(filteredProducts, searchQuery);
    }

    filteredProducts = filterProductsByCategory(filteredProducts, category);
    filteredProducts = filterProductsByBrand(filteredProducts, brand);
    filteredProducts = filterProductsByPrice(filteredProducts, maxPrice);
    filteredProducts = filterProductsByStock(filteredProducts, inStockOnly);

    const sortBy = document.getElementById('sort-by').value;
    const sortedProducts = sortProducts(filteredProducts, sortBy);

    displayProducts(sortedProducts);
    updateProductCount(sortedProducts);
}

function displayProducts(products) {
    const productList = document.getElementById('product-list');
    productList.innerHTML = ''; 

    if (products.length === 0) {

        const row = document.createElement('tr');
        row.innerHTML = `
            <td colspan="5" style="text-align: center; padding: 20px;">
                <img src="/Website Beta/IMAGES/Image complémentaires/Interdiction.jpg  style="margin-bottom: 10px;">
                <p style="font-size: 18px; color: red;">Aucun produit ne correspond à votre recherche</p>
            </td>
        `;
        productList.appendChild(row);
    } else {

        products.forEach(product => {
            const row = document.createElement('tr');
            row.innerHTML = `
                <td><img src="${product.image}" alt="${product.name}" width="100"></td>
                <td>${product.name}</td>
                <td>${product.description}</td>
                <td>${product.availability}</td>
                <td>${product.price}</td>
                <td><button class="add-to-cart">🛒 Ajouter au panier</button></td>
            `;
            productList.appendChild(row);
        });
    }
}

