function displayProducts(products) {
    const productList = document.getElementById('product-list');
    productList.innerHTML = ''; 

    if (products.length === 0) {

        const row = document.createElement('tr');
        row.innerHTML = `
            <td colspan="6" style="text-align: center; padding: 20px;">
                <img src="../IMAGES/Image complémentaires/interdiction.jpg" alt="Aucun produit" width="50" style="margin-bottom: 10px;">
                <p style="font-size: 18px; color: red;">Aucun produit ne correspond à votre recherche</p>
            </td>
        `;
        productList.appendChild(row);
    } else {

        products.forEach(product => {
            const row = document.createElement('tr');
            row.innerHTML = `
                <td><img src="${product.image}" alt="${product.name}" width="100"></td>
                <td>${product.name}</td>
                <td>${product.description}</td>
                <td>${product.availability}</td>
                <td class="price">${product.price}</td>
                <td><button class="add-to-cart">🛒 Ajouter au panier</button></td>
            `;
            productList.appendChild(row);

            const addToCartButton = row.querySelector('.add-to-cart');
            addToCartButton.addEventListener('click', () => {
                const productName = product.name;
                const productPrice = product.price;
                const productImage = product.image;

                const selectedProduct = { 
                    name: productName, 
                    price: productPrice, 
                    image: productImage 
                };

                let existingProducts = JSON.parse(localStorage.getItem('selectedProducts')) || [];
                existingProducts.push(selectedProduct);
                localStorage.setItem('selectedProducts', JSON.stringify(existingProducts));

                console.log('Produit ajouté au panier :', selectedProduct);

                window.location.href = '/Website Beta/Page du panier/Panier.html';
            });
        });
    }
}